import sys
from pathlib import Path

FILES = {'starter.py': 'from pathlib import Path\nimport pandas as pd\n\nROOT = Path(__file__).resolve().parent\nREQUIRED_COLUMNS = {"date", "subject", "grade", "description"}\n\ndef load_grades(path=ROOT / "grades.csv"):\n    df = pd.read_csv(path, dtype={"grade": "string", "subject": "string"})\n    missing = REQUIRED_COLUMNS - set(df.columns)\n    if missing:\n        raise ValueError("Missing required columns: " + ", ".join(sorted(missing)))\n    df["date"] = pd.to_datetime(df["date"], errors="coerce")\n    df["subject"] = df["subject"].str.strip()\n    df["grade"] = df["grade"].str.strip()\n    df["grade_base"] = pd.to_numeric(df["grade"].str.extract(r"^([1-6])[+-]?$", expand=False), errors="coerce")\n    return df\n\ndef grades_below(df, threshold=3):\n    return df.loc[df["grade_base"] < threshold].copy()\n\ndef grades_for_subject(df, subject):\n    return df.loc[df["subject"].str.contains(subject, case=False, na=False, regex=False)].copy()\n\ndef grades_between_dates(df, date_from, date_to):\n    start = pd.to_datetime(date_from, format="%Y-%m-%d", errors="raise")\n    end = pd.to_datetime(date_to, format="%Y-%m-%d", errors="raise")\n    if pd.isna(start) or pd.isna(end) or start > end:\n        raise ValueError("Enter valid dates with the start no later than the end.")\n    return df.loc[df["date"].between(start, end, inclusive="both")].copy()\n\ndef report(df, **filters):\n    unknown = set(filters) - set(df.columns)\n    if unknown:\n        raise ValueError("Unknown columns: " + ", ".join(sorted(unknown)))\n    mask = pd.Series(True, index=df.index)\n    for column, value in filters.items():\n        mask &= df[column].eq(value).fillna(False)\n    return df.loc[mask].copy()\n\ndef summary_by_subject(df):\n    return df.groupby("subject", dropna=False).agg(record_count=("grade", "size"), average_base_grade=("grade_base", "mean")).reset_index()\n\ndef multiple_filters(df):\n    filters = {}\n    print("Exact filters, combined with AND. Columns:", ", ".join(df.columns))\n    while True:\n        column = input("Column (Enter to run): ").strip()\n        if not column:\n            return report(df, **filters)\n        if column not in df.columns:\n            raise ValueError("Unknown column: " + column)\n        value = input("Exact value: ").strip()\n        if column == "date":\n            value = pd.to_datetime(value, format="%Y-%m-%d", errors="raise")\n            if pd.isna(value):\n                raise ValueError("A date is required.")\n        elif column == "grade_base":\n            value = float(value)\n        filters[column] = value\n\ndef main():\n    import argparse\n    parser = argparse.ArgumentParser(description="Local-only grade exploration")\n    parser.add_argument("--csv", type=Path, default=ROOT / "grades.csv")\n    args = parser.parse_args()\n    try:\n        df = load_grades(args.csv)\n    except (OSError, ValueError) as exc:\n        print("Could not load CSV:", exc)\n        print("Create grades.csv locally or use --csv sample_grades.csv for fictional data.")\n        return\n    if df.empty:\n        print("No records found.")\n        return\n    print(df.head().to_string(index=False))\n    print(f"Records: {len(df)}; invalid dates: {df[\'date\'].isna().sum()}; nonnumeric grades: {df[\'grade_base\'].isna().sum()}")\n    while True:\n        print("\\n1 Below base grade\\n2 Subject search\\n3 Date range\\n4 Multiple exact filters\\n5 Subject summary\\n6 Exit")\n        try:\n            choice = input("Choose: ").strip()\n            if choice == "6":\n                break\n            if choice == "1":\n                result = grades_below(df, float(input("Below: ")))\n            elif choice == "2":\n                result = grades_for_subject(df, input("Subject: ").strip())\n            elif choice == "3":\n                result = grades_between_dates(df, input("From YYYY-MM-DD: "), input("To YYYY-MM-DD: "))\n            elif choice == "4":\n                result = multiple_filters(df)\n            elif choice == "5":\n                result = summary_by_subject(df)\n                print("Simple unweighted base-grade mean, not an official term grade.")\n            else:\n                print("Choose 1-6.")\n                continue\n            print(result.to_string(index=False) if not result.empty else "No matching records.")\n        except ValueError as exc:\n            print("Invalid input:", exc)\n        except (EOFError, KeyboardInterrupt):\n            print("\\nGoodbye.")\n            break\n\nif __name__ == "__main__":\n    main()\n', 'inspect_librus_pdf.py': '"""Inspect a PDF locally. Outputs may contain private information."""\nimport argparse\nimport csv\nfrom pathlib import Path\nimport pdfplumber\n\nROOT = Path(__file__).resolve().parent\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument("pdf_path", type=Path)\n    args = parser.parse_args()\n    path = args.pdf_path.expanduser()\n    if not path.is_file() or path.suffix.lower() != ".pdf":\n        parser.error("Provide an existing PDF file.")\n    output = ROOT / "private_work"\n    output.mkdir(exist_ok=True)\n    print("Local processing only. Do not share extracted text or tables.")\n    count = 0\n    try:\n        with pdfplumber.open(path) as pdf:\n            for number, page in enumerate(pdf.pages, 1):\n                print(f"Page {number} text preview:")\n                print((page.extract_text() or "No selectable text.")[:3000])\n                for index, table in enumerate(page.extract_tables() or [], 1):\n                    rows = [[(cell or "").replace("\\n", " ").strip() for cell in row] for row in table if row and any(cell for cell in row)]\n                    if not rows:\n                        continue\n                    target = output / f"page_{number:03d}_table_{index:02d}.csv"\n                    with target.open("w", newline="", encoding="utf-8-sig") as handle:\n                        csv.writer(handle).writerows(rows)\n                    count += 1\n                    print("Saved:", target.name)\n    except Exception as exc:\n        print("PDF inspection failed:", exc)\n        return 1\n    print(f"Tables saved: {count}. Check alignment manually.")\n    print("Create grades.csv locally: date,subject,grade,description")\n    print("For scanned/unsupported PDFs, manually enter selected records locally.")\n    return 0\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n', 'test_starter.py': 'import pandas as pd\nimport pytest\nfrom starter import load_grades, grades_below, grades_for_subject, grades_between_dates, report, summary_by_subject\n\n@pytest.fixture\ndef df():\n    from pathlib import Path\n    return load_grades(Path(__file__).parent / "sample_grades.csv")\n\ndef test_below(df):\n    assert grades_below(df, 3)["grade"].tolist() == ["2"]\n\ndef test_subject(df):\n    assert len(grades_for_subject(df, "MATH")) == 2\n\ndef test_dates(df):\n    assert len(grades_between_dates(df, "2026-09-10", "2026-09-12")) == 2\n\ndef test_reversed(df):\n    with pytest.raises(ValueError):\n        grades_between_dates(df, "2026-10-01", "2026-09-01")\n\ndef test_report(df):\n    assert len(report(df, subject="Mathematics", grade="4+")) == 1\n    assert len(report(df)) == len(df)\n    assert len(report(df, date=pd.Timestamp("2026-09-10"))) == 1\n\ndef test_unknown(df):\n    with pytest.raises(ValueError, match="Unknown columns"):\n        report(df, unknown=1)\n\ndef test_summary(df):\n    row = summary_by_subject(df).set_index("subject").loc["Mathematics"]\n    assert row["record_count"] == 2\n    assert row["average_base_grade"] == 3\n', 'requirements.txt': 'pandas>=2.0\npdfplumber>=0.10\npytest>=7.0\n', 'sample_grades.csv': 'date,subject,grade,description\n2026-09-10,Mathematics,4+,Fictional quiz\n2026-09-12,Mathematics,2,Fictional homework\n2026-10-01,Programming,5,Fictional project\n2026-10-05,Polish,3-,Fictional essay\n', '.gitignore': '.venv/\n__pycache__/\n.pytest_cache/\n*.pdf\ngrades.csv\nprivate_work/\n', 'REPORT.md': '# Librus Intelligence report\n\nThe application reads a locally cleaned CSV and uses Pandas for below-grade, subject, inclusive date-range and multiple exact-match queries. It groups records by subject to count rows and calculate mean base grades. All demonstration records are fictional.\n\nThe base-grade mean is not an official term grade: plus/minus modifiers are removed, weights are not supplied, and no school or teacher grading policy is implemented. Invalid dates and unrecognized grades become missing values. Missing numeric grades are excluded from the mean but included in record counts.\n\nThe PDF inspector processes files locally and exports candidate tables, not a guaranteed clean CSV. The user must verify alignment and create grades.csv locally. No code uploads grade data. Keep PDFs, grades.csv and private_work private. Submit code and this nonpersonal report only.\n', 'README.md': '# Librus Intelligence\n\nRun python install.py from this folder. Python 3.10+ is required. The installer creates files next to itself, skips existing files, and installs dependencies in a local .venv. Package installation requires internet; personal records are not uploaded.\n\nRun the generated run.py using python run.py. For fictional data: python run.py --csv sample_grades.csv\n\nInspect your own PDF: python run.py --inspect "path/to/export.pdf"\nReview private_work locally and manually create grades.csv with columns date,subject,grade,description. Dates should be YYYY-MM-DD. Then use python run.py.\n\nRun tests: python run.py --test\n\nDo not commit or submit your PDF, grades.csv, private_work, or screenshots with personal records. Git ignore rules are not protection for files already tracked. Do not force-add private files. Submit only code and the anonymous report.\n', 'run.py': 'import subprocess\nimport sys\nfrom pathlib import Path\nroot = Path(__file__).resolve().parent\npython = root / ".venv" / ("Scripts/python.exe" if sys.platform == "win32" else "bin/python")\nif not python.is_file():\n    raise SystemExit("Run python install.py first.")\nargs = sys.argv[1:]\nif args and args[0] == "--inspect":\n    command = [str(python), str(root / "inspect_librus_pdf.py"), *args[1:]]\nelif args and args[0] == "--test":\n    command = [str(python), "-m", "pytest", str(root / "test_starter.py"), *args[1:]]\nelse:\n    command = [str(python), str(root / "starter.py"), *args]\nraise SystemExit(subprocess.call(command, cwd=root))\n'}

def main():
    if sys.version_info < (3, 10):
        raise SystemExit("Python 3.10 or newer is required.")
    root = Path(__file__).resolve().parent
    for name, content in FILES.items():
        target = root / name
        if name == ".gitignore" and target.exists():
            existing = target.read_text(encoding="utf-8")
            additions = [line for line in content.splitlines() if line not in existing.splitlines()]
            if additions:
                with target.open("a", encoding="utf-8") as handle:
                    handle.write("\n" + "\n".join(additions) + "\n")
        elif target.exists():
            print("Kept existing:", name)
        else:
            target.write_text(content, encoding="utf-8")
            print("Created:", name)
    environment = root / ".venv"
    python = environment / ("Scripts/python.exe" if sys.platform == "win32" else "bin/python")
    if not python.exists():
        subprocess.run([sys.executable, "-m", "venv", str(environment)], check=True)
    subprocess.run([str(python), "-m", "pip", "install", "--upgrade", "pip"], check=True)
    subprocess.run([str(python), "-m", "pip", "install", "pandas>=2.0", "pdfplumber>=0.10", "pytest>=7.0"], check=True)
    print("Installed. Fictional demo: python run.py --csv sample_grades.csv")
    print("Private records: create grades.csv locally, then python run.py")
    print("Tests: python run.py --test")

if __name__ == "__main__":
    try:
        main()
    except (OSError, subprocess.CalledProcessError) as exc:
        print("Installation failed:", exc, file=sys.stderr)
        print("Check Python venv support and your internet connection, then rerun.", file=sys.stderr)
        raise SystemExit(1)